dtsPropsFor.TaskChip:
/** The normalized calendar record to render. */
item: CalendarItem;
/** Hex or CSS colour driving the chip's tint. */
accent: string;
/** 'xs' calendar cell | 'sm' week untimed lane | 'md' calendar sidebar. Default 'sm'. */
size?: 'xs' | 'sm' | 'md';
/** Chip skin: `faint` (default) = raised faint-tint row with a neutral-ink pressed title; `solid` = saturated tab with a cream-knockout title. */
variant?: 'faint' | 'solid';
showTime?: boolean;
isSelected?: boolean;
isDragging?: boolean;
onSelect?: (item: CalendarItem) => void;
onToggle?: (id: number, completed: boolean) => void;
/** Arms a drag from the originating pointer event (see usePointerDrag). */
onPointerDown?: (e: React.PointerEvent) => void;

dtsPropsFor.TimeBlock:
item: CalendarItem;
accent: string;
/** Column index when several blocks share an hour. */
slot?: number;
totalCols?: number;
isSelected?: boolean;
isDragging?: boolean;
isResizing?: boolean;
/** Live geometry while dragging/resizing (start or end fraction override). */
liveOverride?: { start?: number; end?: number } | null;
/** Picks the row height, block floor and lane inset. Default 'comfortable'. */
density?: 'comfortable' | 'compact';
/** Which timeline this block sits in. Today's single column can afford more air (and a bigger title) than Week's seven lanes. */
surface?: 'week' | 'day';
/** Clock for chip state; pass a frozen Date in tests. */
now?: Date;
onSelect?: (item: CalendarItem) => void;
onToggle?: (id: number, completed: boolean) => void;
/** Arm a move / resize drag from the originating pointer event (usePointerDrag). */
onBeginDrag?: (e: React.PointerEvent) => void;
onBeginResize?: (e: React.PointerEvent) => void;

dtsPropsFor.AllDayBar:
/** Placement of one multi-day event across the week's 7 columns, as produced by `layoutBars()`. */
bar: {
  /** The event itself. NOTE the field is `ev`, not `item`. */
  ev: CalendarItem;
  startCol: number;
  endCol: number;
  /** True when the event began before the visible week — squares off that end. */
  continuesLeft: boolean;
  continuesRight: boolean;
  /** Stacking lane within the all-day row. */
  lane: number;
};
color: string;
/** Absolute offset within the all-day lane, in px. */
top: number;
height: number;
isSelected?: boolean;
isDragging?: boolean;
/** Arms a drag from the originating pointer event (see usePointerDrag). */
onPointerDown?: (e: React.PointerEvent) => void;
onClick?: (e: React.MouseEvent) => void;

dtsPropsFor.TimelinePreview:
/** Live drag state; renders nothing while `overFrac` is null. */
drag: DragState;
sourceColorOf: (source: string | undefined) => string;
/** Must match the grid the ghost is drawn over, or the preview lands at a different minute than the drop does. */
density?: 'comfortable' | 'compact';

dtsPropsFor.CalendarView:
items: CalendarItem[];
/** Today's date as YYYY-MM-DD. */
today: string;
selectedId?: number | null;
readonly?: boolean;
resolvers?: Partial<CardResolvers>;
drag?: DragAdapter;
onSelect?: (item: CalendarItem) => void;
onToggle?: (id: number, completed: boolean) => void;
onAddItem?: (partial: Partial<CalendarItem>) => void;
onUpdateItem?: (id: number, patch: Partial<CalendarItem>) => void;
onWeekJump?: (iso: string) => void;
/** Show the unscheduled-tasks rail beside the month grid. Off by default. */
sidebar?: boolean;
