createSource?: string;
onAddOnDate?: (date: string) => void;
/** Framing density. 'comfortable' (default) is the full-air layout; 'compact' tightens gaps + padding for small mounts. */
density?: 'comfortable' | 'compact';
/** Content pinned to the bottom of the view (a colophon, a legend, a status line). Ignored at 'compact'. */
foot?: React.ReactNode;

